          destRight[di + 1] += srcRight[i + 1];
          destLeft[di + 2] += srcLeft[i + 2];
          destRight[di + 2] += srcRight[i + 2];
          destLeft[di + 3] += srcLeft[i + 3];
          destRight[di + 3] += srcRight[i + 3];
          i += 4; di += 4;
